import React, { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import styles from './conversation_style.module.css';
import { callApi } from '../api/client';

// Core system prompts (lowercased for filtering)
const INITIAL_CORE = `
you are an ai assisting with business problem definition.
the user will provide a brief business problem statement.
your task is:
1. analyze the user's problem statement.
2. decide if you need more information.
3. if more info needed, ask ONE clarifying question.
4. if enough, START your response with EXACTLY: "ready to formulate problem."
`.trim().toLowerCase();

const NEXT_CORE = `
you are continuing to assist with business problem definition.
the user has responded to your previous question.
your task is:
1. review the conversation.
2. if you still need info, ask ONE clarifying question.
3. otherwise, START your response with EXACTLY: "ready to formulate problem."
`.trim().toLowerCase();

export default function Conversation() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const endRef = useRef(null);

  // UI state
  const [conversation, setConversation] = useState([]);
  const [userResponse, setUserResponse] = useState('');
  const [finalProblem, setFinalProblem] = useState('');
  const [pipeline, setPipeline] = useState('initializing'); 
  const [loadingMsg, setLoadingMsg] = useState('');

  // Remove file-details and system prompt echoes
  const filterConv = (conv) =>
    (conv || []).filter(m =>
      !m.startsWith('FileDetails:')
      && !m.toLowerCase().includes(INITIAL_CORE)
      && !m.toLowerCase().includes(NEXT_CORE)
    );

  // Handle the AI → UI conversation state update
  function updateConversation(conv, finalProb) {
    setConversation(filterConv(conv));
    if (finalProb) {
      setFinalProblem(finalProb);
      setPipeline('complete');
    } else {
      setPipeline('conversation');
    }
  }

  // 1) On mount: load initial conversation (either from router state or via GET)
  useEffect(() => {
    const initConv = state?.conversation;
    const initFinal = state?.final_problem;
    if (initConv) {
      updateConversation(initConv, initFinal);
    } else {
      callApi('conversation','GET')
        .then(data => {
          if (data.conversation) updateConversation(data.conversation, data.final_problem);
          else throw new Error('No conversation');
        })
        .catch(err => {
          console.error(err);
          setPipeline('error');
          setLoadingMsg('Failed to load conversation');
        });
    }
  }, [state]);

  // 2) Auto‑scroll on new messages
  useEffect(() => {
    if (pipeline === 'conversation') {
      endRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [conversation, pipeline]);

  // 3) Submit user reply
  const handleSubmit = async e => {
    e.preventDefault();
    if (!userResponse.trim() || pipeline !== 'conversation') return;
    const reply = userResponse.trim();
    setConversation(c => [...c, `User: ${reply}`]);
    setUserResponse('');
    setPipeline('sending');

    try {
      const data = await callApi('conversation','POST',{user_response: reply});
      updateConversation(data.conversation, data.final_problem);
    } catch(err) {
      console.error(err);
      setPipeline('error');
      setLoadingMsg('Failed to send your response');
    }
  };

  // 4) Once conversation_complete → trigger pipeline steps
  useEffect(() => {
    if (pipeline !== 'complete' && pipeline !== 'conversation') return;

    async function runStep(step) {
      try {
        let res;
        switch(step) {
          case 'conversation':
            // User done talking: move to plan
            setPipeline('processing_plan');
            return;
          case 'processing_plan':
            setLoadingMsg('Planning things out...');
            res = await callApi('superllm','POST');
            if (res.status==='plan_generated'||res.status==='ml_plan_exists') setPipeline('processing_eda');
            else throw new Error(res.error||res.details||'Plan failed');
            return;
          case 'processing_eda':
            setLoadingMsg('Running guided EDA...');
            res = await callApi('dataanalysis','POST');
            if (res.status==='success') setPipeline('processing_ml');
            else throw new Error(res.error||res.details||'EDA failed');
            return;
          case 'processing_ml':
            setLoadingMsg('Running ML...');
            res = await callApi('ml','POST');
            if (res.status==='success') {
              setLoadingMsg('Generating visualizations...');
              await callApi('vlm','POST').catch(e=>console.warn('VLM error',e));
              setPipeline('complete');
            } else throw new Error(res.error||res.details||'ML failed');
            return;
          default:
            return;
        }
      } catch(err) {
        console.error(err);
        setPipeline('error');
        setLoadingMsg(err.message||'Pipeline error');
      }
    }

    // small delay between stages
    const next = pipeline === 'complete' ? null : pipeline;
    if (next) {
      const t = setTimeout(()=>runStep(next), 500);
      return ()=>clearTimeout(t);
    }
  }, [pipeline, navigate]);

  // 5) On `complete`, redirect after a pause
  useEffect(() => {
    if (pipeline === 'complete') {
      setLoadingMsg('✅ Complete! Redirecting...');
      const t = setTimeout(()=>navigate('/dashboard'),1500);
      return ()=>clearTimeout(t);
    }
  }, [pipeline, navigate]);

  // Render
  return (
    <div className={styles.conversationPageWrapper}>
      <div className={styles.chatWindow}>
        <h1>
          {pipeline==='initializing' && 'Initializing...'}
          {pipeline==='conversation' && 'Defining the Business Problem'}
          {pipeline==='sending' && 'Sending...'}
          {pipeline==='processing_plan' && 'Planning...'}
          {pipeline==='processing_eda' && 'EDA...'}
          {pipeline==='processing_ml' && 'ML...'}
          {pipeline==='complete' && 'Done'}
          {pipeline==='error' && 'Error'}
        </h1>

        <div className={styles.conversation}>
          {conversation.map((m,i) => {
            const isUser = m.startsWith('User:');
            const text = m.replace(isUser?'User:':'System:','').trim();
            return (
              <div key={i}
                className={isUser?styles.userBubble:styles.aiBubble}>
                {text}
              </div>
            );
          })}
          <div ref={endRef} />
        </div>

        {pipeline==='conversation' && (
          <form className={styles.responseForm} onSubmit={handleSubmit}>
            <input
              value={userResponse}
              onChange={e=>setUserResponse(e.target.value)}
              placeholder="Type your answer..."
            />
            <button type="submit" disabled={!userResponse.trim()}>
              Send
            </button>
          </form>
        )}

        {(pipeline!=='conversation' && loadingMsg) && (
          <div className={styles.pipelineMessage}>
            ⏳ {loadingMsg}
          </div>
        )}

        {pipeline==='complete' && finalProblem && (
          <div className={styles.finalProblemDisplay}>
            <h2>Final Business Problem:</h2>
            <p>{finalProblem}</p>
          </div>
        )}

        {pipeline==='error' && (
          <div className={styles.errorMessage}>
            ❌ {loadingMsg}
          </div>
        )}
      </div>
    </div>
  );
}
